def _join(items: list[str], language: str) -> str:
    if len(items) == 1:
        return items[0]
    conjunction = "ve" if language == "tr" else "and"
    if len(items) == 2:
        return f"{items[0]} {conjunction} {items[1]}"
    separator = ", and " if language == "en" else " ve "
    return ", ".join(items[:-1]) + separator + items[-1]


def _label(label: str, language: str, count: int = 1) -> str:
    normalized = label.casefold().strip()
    known = _LABELS.get(normalized)
    if known is not None:
        singular, plural = known[language]
    else:
        singular = label.strip()
        plural = singular if language == "tr" else singular + "s"
    if language == "tr":
        number = _TR_NUMBERS.get(count, str(count))
        return f"{number} {singular}"
    noun = singular if count == 1 else plural
    number = _EN_NUMBERS.get(count, str(count))
    return f"{number} {noun}"


def _bare_label(label: str, language: str) -> str:
    known = _LABELS.get(label.casefold().strip())
    return known[language][0] if known is not None else label.strip()


def _quoted(text: str) -> str:
    return f"“{text}”"


def _object_groups(objects: tuple[DetectedObject, ...]) -> list[tuple[str, list[DetectedObject]]]:
    groups: OrderedDict[str, list[DetectedObject]] = OrderedDict()
    for item in objects:
        groups.setdefault(item.label, []).append(item)
    return list(groups.items())


@runtime_checkable
class DescriptionProjection(Protocol):
    def project(self, field: Field, language: str, detail: str) -> TextProjection: ...


class NaturalDescriptionProjection:
    def __init__(self, thresholds: ConfidenceThresholds | None = None) -> None:
        self.thresholds = thresholds or ConfidenceThresholds()

    def project(self, field: Field, language: str, detail: str) -> TextProjection:
        if language not in OUTPUT_LANGUAGES:
            raise ValueError("language must be tr or en")
        if detail not in DETAIL_LEVELS:
            raise ValueError("detail must be compact, balanced or detailed")
        objects = tuple(
            item for item in field.scene.objects if item.confidence >= self.thresholds.object_min
        )
        texts = tuple(
            item for item in field.scene.texts if item.confidence >= self.thresholds.ocr_min
        )
        warnings = []
        if not objects:
            warnings.append("no_objects_above_threshold")
        if not texts:
            warnings.append("no_ocr_above_threshold")
        if not objects and not texts:
            sentence = (
                "Görüntüde güven eşiğini geçen nesne veya metin bulunamadı."
                if language == "tr"
                else "No object or text passed the configured confidence thresholds."
            )
            return TextProjection((sentence,), language, detail, tuple(warnings))
        groups = _object_groups(objects)
        sentences = []
        if detail == "compact":
            sentences.extend(self._compact(groups[:4], texts[:2], language))
        else:
            sentences.extend(self._balanced(field, groups, texts, language))
            relation_limit = 2 if detail == "balanced" else 8
            sentences.extend(self._relations(field, objects, language, relation_limit))
            if detail == "detailed":
                sentences.extend(self._attributes(objects, language))
        return TextProjection(tuple(sentences), language, detail, tuple(warnings))

    def _compact(self, groups, texts, language: str) -> list[str]:
        sentences = []
        if groups:
            phrases = [_label(label, language, len(items)) for label, items in groups]
            if language == "tr":
                sentences.append(f"Görüntüde {_join(phrases, language)} bulunuyor.")
            else:
                sentences.append(f"The image contains {_join(phrases, language)}.")
        if texts:
            values = [_quoted(item.text) for item in texts]
            if language == "tr":
                noun = "metni" if len(values) == 1 else "metinleri"
                sentences.append(f"{_join(values, language)} {noun} okunuyor.")
            else:
                noun, verb = ("text", "is") if len(values) == 1 else ("texts", "are")
                sentences.append(f"The {_join(values, language)} {noun} {verb} visible.")
        return sentences

    def _balanced(self, field: Field, groups, texts, language: str) -> list[str]:
        sentences = []
        positioned = []
        for label, items in groups:
            regions = {field.region_of(item.id) for item in items}
            regions.discard(None)
            if len(regions) == 1:
                region = _REGIONS[next(iter(regions))][language]
            else:
                region = "farklı bölgelerinde" if language == "tr" else "in different areas"
            positioned.append((_label(label, language, len(items)), region))
        if positioned:
            if language == "tr":
                first_phrase, first_region = positioned[0]
                clauses = [f"Görüntünün {first_region} {first_phrase}"]
                clauses.extend(f"{region} {phrase}" for phrase, region in positioned[1:])
                sentences.append(f"{'; '.join(clauses)} bulunuyor.")
            else:
                clauses = [f"{phrase} {region}" for phrase, region in positioned]
                sentences.append(f"The image contains {'; '.join(clauses)}.")
        if texts:
            regions = {field.region_of(item.id) for item in texts}
            regions.discard(None)
            values = [_quoted(item.text) for item in texts]
            if len(regions) == 1:
                region = _REGIONS[next(iter(regions))][language]
            else:
                region = "farklı bölgelerinde" if language == "tr" else "in different areas"
            if language == "tr":
                noun = "metni" if len(values) == 1 else "metinleri"
                sentences.append(f"Görüntünün {region} {_join(values, language)} {noun} okunuyor.")
            else:
                noun, verb = ("text", "is") if len(values) == 1 else ("texts", "are")
                sentences.append(f"The {_join(values, language)} {noun} {verb} visible {region}.")
        return sentences

    def _relations(
        self,
        field: Field,
        objects: tuple[DetectedObject, ...],
        language: str,
        limit: int,
    ) -> list[str]:
        by_id = {item.id: item for item in objects}
        rows = []
        seen = set()
        family = {
            "left_of": "horizontal",
            "right_of": "horizontal",
            "above": "vertical",
            "below": "vertical",
            "inside": "containment",
            "contains": "containment",
            "near": "distance",
            "far": "distance",
            "overlapping": "overlap",
        }
        for item in field.edges:
            if item.source_kind != "unit" or item.target_kind != "unit":
                continue
            if item.certainty < self.thresholds.relation_min:
                continue
            key = (tuple(sorted((item.source, item.target))), family[item.predicate])
            if key in seen or item.source not in by_id or item.target not in by_id:
                continue
            seen.add(key)
            sentence = self._relation_sentence(
                by_id[item.source], item.predicate, by_id[item.target], language
            )
            if sentence in rows:
                continue
            rows.append(sentence)
            if len(rows) >= limit:
                break
        semantic_keys = {
            (item.source, item.predicate, item.target)
            for item in field.edges
            if item.source_kind == "unit" and item.target_kind == "unit"
        }
        for relation in field.scene.relations:
            if len(rows) >= limit:
                break
            if relation.confidence < self.thresholds.relation_min:
                continue
            if (relation.source, relation.predicate, relation.target) in semantic_keys:
                continue
            if relation.source not in by_id or relation.target not in by_id:
                continue
            sentence = self._semantic_relation_sentence(
                by_id[relation.source], relation.predicate, by_id[relation.target], language
            )
            if sentence is not None:
                if sentence not in rows:
                    rows.append(sentence)
        return rows

    def _relation_sentence(
        self, source: DetectedObject, predicate: str, target: DetectedObject, language: str
    ) -> str:
        source_name = _label(source.label, language, 1)
        target_name = _bare_label(target.label, language)
        if language == "en":
            article = "an" if target_name[:1].lower() in "aeiou" else "a"
            target_phrase = f"{article} {target_name}"
            templates = {
                "left_of": "{source} is to the left of {target}.",
                "right_of": "{source} is to the right of {target}.",
                "above": "{source} is above {target}.",
                "below": "{source} is below {target}.",
                "near": "{source} is near {target}.",
                "far": "{source} is far from {target}.",
                "overlapping": "{source} overlaps {target} in the image.",
                "inside": "{source} is inside {target}.",
                "contains": "{source} contains {target} geometrically.",
            }
            return templates[predicate].format(
                source=source_name.capitalize(), target=target_phrase
            )
        genitive = _TR_GENITIVE.get(target_name, f"{target_name} öğesinin")
        target_plain = _label(target.label, language, 1)
        templates = {
            "left_of": "{source}, {target} solunda.",
            "right_of": "{source}, {target} sağında.",
            "above": "{source}, {target} üstünde.",
            "below": "{source}, {target} altında.",
            "near": "{source}, {target} yakınında.",
            "far": "{source}, {target} uzağında.",
            "overlapping": "{source} ile {plain} görüntüde örtüşüyor.",
            "inside": "{source}, {target} içinde.",
            "contains": "{source}, {plain} öğesini geometrik olarak içeriyor.",
        }
        return templates[predicate].format(
            source=source_name.capitalize(), target=genitive, plain=target_plain
        )

    def _semantic_relation_sentence(
        self, source: DetectedObject, predicate: str, target: DetectedObject, language: str
    ) -> str | None:
        source_name = _label(source.label, language, 1).capitalize()
        target_name = _label(target.label, language, 1)
        templates = {
            "tr": {
                "holding": "{source}, {target} tutuyor.",
                "carrying": "{source}, {target} taşıyor.",
                "riding": "{source}, {target} üzerinde ilerliyor.",
            },
            "en": {
                "holding": "{source} is holding {target}.",
                "carrying": "{source} is carrying {target}.",
                "riding": "{source} is riding {target}.",
            },
        }
        template = templates[language].get(predicate)
        return template.format(source=source_name, target=target_name) if template else None

    def _attributes(self, objects: tuple[DetectedObject, ...], language: str) -> list[str]:
        rows = []
        for item in objects:
            for attribute in item.attributes:
                if attribute.confidence < self.thresholds.attribute_min:
                    continue
                owner = _label(item.label, language, 1)
                value = _quoted(attribute.value)
                if language == "tr":
                    rows.append(f"{owner.capitalize()} için {attribute.name} değeri {value}.")
                else:
                    rows.append(f"The {attribute.name} value for {owner} is {value}.")
        return rows


class TextSurface:
    def emit(self, projection: TextProjection) -> str:
        return " ".join(projection.sentences)
